"""Pin this local frontend/backend to the processed release; no network calls."""
import hashlib
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]


def main():
    data = (ROOT/'website/data/osm-complete/proposal-roads/manifest.json').read_bytes()
    manifest = json.loads(data)
    (ROOT/'apps-script/RegistryConfig.gs').write_text(
        '// Generated by website-plan/osm-complete/configure.py. Local review only.\n'
        'var ROAD_REGISTRY_VERSION = '+json.dumps(manifest['version'])+';\n'
        'var ROAD_MANIFEST_SHA256 = '+json.dumps(hashlib.sha256(data).hexdigest())+';\n', encoding='utf-8')
    path = ROOT/'website/js/site-config.js'
    source, count = re.subn(r"proposalNetworkVersion: '[^']+'", "proposalNetworkVersion: '"+manifest['version']+"'", path.read_text(encoding='utf-8'))
    assert count == 1
    path.write_text(source, encoding='utf-8')
    (ROOT/'apps-script/RoadGeometry.gs').write_bytes((ROOT/'website/js/road-geometry.js').read_bytes())
    print('Pinned', manifest['version'])


if __name__ == '__main__':
    main()
